  "bopomofo/images/airplane.jpg",
  "bopomofo/images/cat.jpg",
  "bopomofo/images/cup.jpg",
  "bopomofo/images/egg.jpg",
  "bopomofo/images/grapes.jpg",
  "bopomofo/images/rabbit.jpg",
  "colors/",
  "colors/index.html",
  "colors/images/apple.jpg",
